function conceptDiagram(record){
 const kit=(record.componentKit||[]).slice(0,3);if(!kit.length)return '';
 const short=s=>String(s||'').length>24?String(s).slice(0,22)+'…':s;
 return `<figure class="kw-topology"><svg viewBox="0 0 390 ${kit.length*76+14}" role="img" aria-label="${esc(record.name)}: archive component roles, not applied topology">${kit.map((k,i)=>`<rect x="${28+i*12}" y="${12+i*76}" width="${334-i*24}" height="60" rx="9"/><text x="195" y="${35+i*76}" text-anchor="middle">${esc(short(k.name))}</text><text class="kw-svg-detail" x="195" y="${54+i*76}" text-anchor="middle">${esc(short(k.archetype||k.canonicalKind))}</text>${i<kit.length-1?`<path d="M195 ${72+i*76}v16"/>`:''}`).join('')}</svg><figcaption>Illustrative component roles · connections require design</figcaption></figure>`;
}
function graph(brain){
 const focusId='project:'+context.selected.id,nodes=brain.graph.nodes,edges=brain.graph.edges,focus=nodes.find(n=>n.id===focusId),others=nodes.filter(n=>n.id!==focusId).slice(0,9),height=110+others.length*86;
 const short=(s,n=33)=>s.length>n?s.slice(0,n-1)+'…':s;
 const box=(n,x,y,w,primary=false)=>`<g><title>${esc(n.title+' · '+n.kind)}</title><rect class="${primary?'kw-focus':''}" x="${x}" y="${y}" width="${w}" height="58" rx="8"/><text x="${x+12}" y="${y+23}">${esc(short(n.title))}</text><text class="kw-svg-detail" x="${x+12}" y="${y+43}">${esc(short(n.kind+' · '+n.id,41))}</text></g>`;
 return `<figure class="kw-graph"><svg viewBox="0 0 390 ${height}" role="img" aria-label="Recorded project and retrieved knowledge relationships">${focus?box(focus,16,8,358,true):''}${others.map((n,i)=>{const y=108+i*86,e=edges.find(e=>e.from===n.id||e.to===n.id);return `${e?`<path d="M30 66V${y+29}h22"/>`:''}${box(n,52,y,322)}${e?`<text class="kw-svg-detail" x="64" y="${y-8}">${esc(short(e.relationship,49))}</text>`:''}`;}).join('')}</svg><figcaption>${edges.length} typed relationships · retrieved ideas remain unassessed until reviewed</figcaption></figure><details class="brain-basis"><summary>Inspect the reasoning graph</summary>${edges.map(e=>`<p><code>${esc(e.from)}</code><br>${esc(e.relationship)}<br><code>${esc(e.to)}</code></p>`).join('')||'<p>No connected reasoning recorded for this object.</p>'}</details>`;
}
// A review desk switch point, opened here: the options side by side with what each product is
