  const id=wantReference.replace(/^catalogue:/,'');wantReference='';referenceSourceId='';const record=catalogueRecord(id),state=knowledgeState(p),claim=releasedClaims(p).find(h=>id===h.claim.id||id==='claim:'+h.release.id+':'+h.claim.id),source=state.sources.find(s=>s.id===(claim?.claim.sourceId||id));
